        img.set_valign(Gtk.Align.CENTER)
        top.pack_start(img, False, False, 0)
        info = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=3, valign=Gtk.Align.CENTER)
        tl = Gtk.Box(spacing=10)
